          const byMonth = /* @__PURE__ */ new Map();
          for (const d2 of daily) byMonth.set(d2.date.slice(0, 7), (byMonth.get(d2.date.slice(0, 7)) ?? 0) + d2.count);
          const monthly = [...byMonth.entries()].map(([month, count]) => ({ month, count }));
