          periodB: external_exports.object({ start: external_exports.string().describe("\u8D77 YYYY-MM-DD"), end: external_exports.string().describe("\u6B62 YYYY-MM-DD\uFF08\u542B\u5F53\u5929\uFF09") }).describe("\u7B2C\u4E8C\u4E2A\u65E5\u671F\u6BB5"),
          kind: external_exports.enum(["c2c", "group"]).optional().describe("\u53EA\u6BD4\u5355\u4E2A\u4F1A\u8BDD\u65F6\u4F20\uFF1Ac2c=\u79C1\u804A / group=\u7FA4\u804A"),
