  // ---- export ----
  /** List conversations with message counts (batch query). */
  listConversationsWithCount: procedure.query(async () => {
    const services2 = requireServices12();
    const contacts = (await services2.recentContacts.getRecentContact(200)).filter((c2) => c2.targetUid);
    const kindOf = (chatType) => {
      const t2 = String(chatType);
      if (t2.includes("GROUP")) return "group";
      if (t2.includes("DATALINE")) return "dataline";
      return "c2c";
    };
    const groupCodes = contacts.filter((c2) => kindOf(c2.chatType) === "group").map((c2) => c2.targetUid);
    const c2cUids = contacts.filter((c2) => kindOf(c2.chatType) === "c2c").map((c2) => c2.targetUid);
    const datalineUids = contacts.filter((c2) => kindOf(c2.chatType) === "dataline").map((c2) => c2.targetUid);
    const account = getAppContext().account;
    const [groupCounts, c2cCounts, datalineCounts] = await Promise.all([
      account?.groupMsgs.countByGroups(groupCodes) ?? Promise.resolve({}),
      account?.c2cMsgs.countByUids(c2cUids) ?? Promise.resolve({}),
      account?.datalineMsgs.countByUids(datalineUids) ?? Promise.resolve({})
    ]);
    return contacts.map((c2) => {
      const kind = kindOf(c2.chatType);
      const messageCount = kind === "group" ? groupCounts[c2.targetUid] ?? 0 : kind === "dataline" ? datalineCounts[c2.targetUid] ?? 0 : c2cCounts[c2.targetUid] ?? 0;
      return { ...recentContactToWire(c2), messageCount };
    });
  }),
